%[text] ## MathieuPendulum.m - Stability Analysis of Parametric Oscillators
%[text] This script demonstrates the use of the PhasorArray Toolbox to analyze
%[text] the stability of the Mathieu equation (Parametric Pendulum).
%[text] It compares Floquet theory (via HSS eigenvalues) with time-domain simulations and generates the Strutt-Ince stability diagram.
%[text] 
%[text] % Reference:
%[text] %   \[1\] Zhou, J. (2008). Derivation and Solution of Harmonic Riccati Equations.
%[text] %   \[2\] PhasorArray Wiki: Example-Mathieu-Pendulum.md

clear; clc; close all;

% --- 1. Parameters & Setup ---
fprintf('--- Mathieu Equation Stability Analysis ---\n'); %[output:95e5c041]

% Standard form: ddx + [a - 2q*cos(2t)] x = 0
% We transform this into a state-space LTP system:
% x1_dot = x2
% x2_dot = -(a - 2q*cos(2t))*x1
% x_dot = A(t)*x

T = pi;             % Period of 2*cos(2t) is pi
omega = 2*pi/T;     % Fundamental frequency (omega = 2)

h_hss = 15;         % Harmonic truncation order for HSS analysis
assetDir = fullfile(pwd, '..', 'docs', 'wiki_assets');

% Check if Asset directory exists (fallback to current if not in repo)
if ~exist(assetDir, 'dir'), assetDir = pwd; end

% --- 2. Time-Domain Evolution (Stable vs Unstable) ---
fprintf('Generating Time-Domain Comparison...\n'); %[output:834c2287]

% Case A: Stable Point (a=2.0, q=0.2)
% Case B: Unstable Point (a=1.0, q=0.5) - First stability tongue
points = [2.0, 0.2; 1.0, 0.5];
titles = {'Stable Case (a=2.0, q=0.2)', 'Unstable Case (a=1.0, q=0.5)'};
fnames = {'mathieu_stable', 'mathieu_unstable'};

fig_time = figure('Name', 'Mathieu_Time_Evolution', 'Position', [100 100 1000 400]); %[output:2ae00f1e]
t_sim = linspace(0, 6*pi, 1000);

for i = 1:2 %[output:group:1a68cbca]
    a = points(i, 1);
    q = points(i, 2);
    
    % Build PhasorArray for A(t)
    A0 = [0 1 ; -a 0];
    A1 = [0 0 ; q 0]; % 2q*cos(2t) = q*(exp(j2t) + exp(-j2t))
    
    Ar = PhasorArray(A0, A1, 'isreal', true);
    sys = PhasorSS(Ar, [0;0], [1 0], 0, T);
    
    % Simulate Initial Condition
    [y, t] = initial(sys, [1; 0], 6*pi); %[output:66ed0667]
    
    subplot(1, 2, i); %[output:2ae00f1e]
    plot(t, squeeze(y), 'LineWidth', 1.5);
    hold on;
    % Overlay the parametric modulation (scaled)
    mod_val = a - 2*q*cos(2*t);
    plot(t, mod_val/max(abs(mod_val))*max(abs(y))*0.2, 'k:', 'LineWidth', 1);
    
    title(titles{i});
    xlabel('Time [s]'); ylabel('x(t)');
    grid on;
    if i==1, legend('Response', 'Param. Modulation', 'Location', 'northeast'); end
end %[output:group:1a68cbca]

% Save Time Evolution Plot
exportgraphics(fig_time, fullfile(assetDir, 'mathieu_time_evolution.svg'), 'BackgroundColor', 'none', 'ContentType', 'vector'); %[output:2ae00f1e]

% --- 3. HSS Spectrum Analysis ---
fprintf('Generating HSS Spectrum (Eigenvalue strings)...\n'); %[output:0216bb01]

fig_spec = figure('Name', 'Mathieu_HSS_Spectrum', 'Position', [100 100 600 500]); %[output:0c1ade20]
colors = lines(2);

for i = 1:2
    a = points(i, 1);
    q = points(i, 2);
    
    A0 = [0 1 ; -a 0];
    A1 = [0 0 ; q 0];
    Ar = PhasorArray(A0, A1, 'isreal', true);
    
    % Compute HSS eigenvalues (Floquet Exponents)
    % Note: HmqNEig is a method of PhasorArray
    ev = Ar.HmqNEig(70, omega); 
    
    plot(real(ev), imag(ev), 'x', 'Color', colors(i,:), 'MarkerSize', 8, ... %[output:0c1ade20]
        'DisplayName', sprintf('a=%.1f, q=%.1f', a, q)); %[output:0c1ade20]
    hold on;
end

% Draw the stability boundary (Imaginary axis)
line([0 0], [-20 20], 'Color', [0.5 0.5 0.5], 'LineStyle', '--', 'HandleVisibility', 'off'); %[output:0c1ade20]
title('HSS Spectrum (Floquet Exponents \mu)'); %[output:0c1ade20]
xlabel('Re(\mu)'); ylabel('Im(\mu)'); %[output:0c1ade20]
legend('Location', 'best'); %[output:0c1ade20]
grid on; %[output:0c1ade20]
ylim([-10 10]);  %[output:0c1ade20]
exportgraphics(fig_spec, fullfile(assetDir, 'mathieu_hss_spectrum.svg'), 'BackgroundColor', 'none', 'ContentType', 'vector'); %[output:0c1ade20]

% --- 4. Strutt-Ince Diagram (Stability Tongues) ---
fprintf('Computing Strutt-Ince Diagram (Full Scan)...\n'); %[output:202f1550]

Na = 80; Nq = 80;
a_range = linspace(0, 4, Na);
q_range = linspace(0, 1.5, Nq);
[A_mesh, Q_mesh] = meshgrid(a_range, q_range);
Stability_Map = zeros(size(A_mesh));

% Fast scan using HSS
% We only need h=5 for a rough stability map
h_scan = 5;

for idx = 1:numel(A_mesh)
    a_val = A_mesh(idx);
    q_val = Q_mesh(idx);
    
    A0 = [0 1 ; -a_val 0];
    A1 = [0 0 ; q_val 0];
    Ar = PhasorArray(A0, A1, 'isreal', true);
    
    % Get max real part of HSS eigenvalues
    ev = Ar.HmqNEig(h_scan, omega);
    Stability_Map(idx) = max(real(ev));
end

fig_tongues = figure('Name', 'Mathieu_Strutt_Ince', 'Position', [100 100 700 600]); %[output:7f8a75b1]
% Threshold for stability
stable_region = (Stability_Map < 1e-5);
imagesc(a_range, q_range, stable_region); %[output:7f8a75b1]
set(gca, 'YDir', 'normal'); %[output:7f8a75b1]
colormap([0.8 0.3 0.3; 0.3 0.8 0.3]); % Red=Unstable, Green=Stable %[output:7f8a75b1]

hold on; %[output:7f8a75b1]
% Plot our two test points
plot(points(1,1), points(1,2), 'ko', 'MarkerFaceColor', 'g', 'MarkerSize', 10); %[output:7f8a75b1]
text(points(1,1)+0.1, points(1,2), 'Stable point', 'FontWeight', 'bold'); %[output:7f8a75b1]
plot(points(2,1), points(2,2), 'ko', 'MarkerFaceColor', 'r', 'MarkerSize', 10); %[output:7f8a75b1]
text(points(2,1)+0.1, points(2,2), 'Unstable point', 'FontWeight', 'bold'); %[output:7f8a75b1]

title('Strutt-Ince Diagram (Stability Tongues)'); %[output:7f8a75b1]
xlabel('Parameter a'); ylabel('Modulation Depth q'); %[output:7f8a75b1]
grid on; %[output:7f8a75b1]
exportgraphics(fig_tongues, fullfile(assetDir, 'mathieu_stability_tongues.svg'), 'BackgroundColor', 'none', 'ContentType', 'vector'); %[output:7f8a75b1] %[output:57d4670b]

fprintf('Successfully generated all Mathieu figures in %s\n', assetDir); %[output:2f6ea85c]


